import re
from urllib.parse import urlsplit

# Qt's .sha256 endpoint is generated by download.qt.io and is not included in
# ordinary rsync mirrors. These exact tar.xz hashes were fetched from the official
# URLs on 2026-11-06, not calculated from an unverified mirror download.
# Source: https://download.qt.io/archive/qt/<major.minor>/<version>/submodules/
#         <module>-everywhere-src-<version>.tar.xz.sha256
# Versions/modules not listed here still require official SHA-256 metadata.
QT_SOURCE_SHA256 = {
    '6.12.0': {
        'qtbase': 'a951bd163c7b80fc6b8c88d7668fb56abf91c152373e13c10666763238131307',
        'qtimageformats': '0943132b5db8de6b6a7f1d162682173e8763c7ed94e80fd39113292845f67762',
        'qtsvg': 'e4ab39534ec97987b1b9b60ef7f4d3253d5912a69f8c713a01753174a4029331',
        'qttranslations': '85929c0c30d6f273f23bd879bb69803ea17b010ab73cab2f8abf95357f6f6bbb',
    },
    '6.8.3': {
        'qtbase': '56001b905601bb9023d399f3ba780d7fa940f3e4861e496a7c490331f49e0b80',
        'qtimageformats': '049bfb99845e4801672aca07c3c4fc4c140f932a3a33faa899419579e33ef1c8',
        'qtsvg': '35eb516460f00f264eb504baa253432384351cf23fb9980a5857190e8deef438',
        'qttranslations': 'c3c61d79c3d8fe316a20b3617c64673ce5b5519b2e45535f49bee313152fa531',
    },
}


def candidate_urls(url):
    """Public mirrors first, original upstream last. Callers validate HTTPS/hash.

    Queries, credentials and nonstandard ports are never forwarded to a proxy.
    GitHub proxy routes are limited to public source archives and release assets.
    Mirror references: https://mirrors.ustc.edu.cn/help/qtproject.html
    https://mirrors.tuna.tsinghua.edu.cn/gnu/
    https://gh-proxy.com/docs/github-accelerator
    """
    parsed = urlsplit(url)
    if (parsed.scheme != 'https' or parsed.username or parsed.password or
            parsed.query or parsed.fragment or parsed.netloc != parsed.hostname):
        return [url]
    host, path = parsed.hostname, parsed.path
    mirrors = []
    if host == 'download.qt.io' and path.startswith(('/archive/qt/', '/official_releases/qt/')):
        if path.endswith(('.sha256', '.sha512', '.mirrorlist', '.meta4')):
            return [url]
        for base in ('https://mirrors.tuna.tsinghua.edu.cn/qt',
                     'https://mirrors.ustc.edu.cn/qtproject',
                     'https://ftp.jaist.ac.jp/pub/qtproject'):
            mirrors.append(base + path)
    elif (host == 'ftp.gnu.org' and path.startswith('/gnu/')) or host == 'ftpmirror.gnu.org':
        # Both GNU hosts can include /gnu/. Mirror roots already include it.
        suffix = path[4:] if path.startswith('/gnu/') else path
        mirrors = ['https://mirrors.tuna.tsinghua.edu.cn/gnu' + suffix,
                   'https://mirrors.ustc.edu.cn/gnu' + suffix]
    elif host == 'github.com' and re.fullmatch(r'/[^/]+/[^/]+/(?:archive/.+|releases/download/.+)', path):
        mirrors = ['https://ghfast.top/' + url, 'https://gh-proxy.org/' + url]
    return list(dict.fromkeys(mirrors + [url]))
